use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var first = true;
    for dish in menu.board() {
        if !first {
            io.write(text: ";")?;
        }
        kitchen.serve(io: io, dish: dish)?;
        first = false;
    }
    return Ok(unit);
}

