use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;

    for entry in signal.today() {
        let rendered = match entry {
            signal.Calm => "calm",
            signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            signal.Fog(density) => "fog:".concat(other: density),
        };

        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
    }

    result
}

