    while i < lineup.length() {
        if i > 0 {
            output = output.concat(other: ",");
        }
        let fed = herd.feed(pony: lineup[i], scoops: 3);
        output = output.concat(other: ledger.render(pony: fed));
        i = i + 1;
    }
    io.write(text: output)?;
    return Ok(unit);
}

