                output = output.concat(other: stable.ledger.render(fed));
            }
            None => {}
        }
        i = i + 1;
    }
    io.write(text: output)?;
    return Ok(unit);
}

use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in feed.frames() {
        let value = match feed.decode(frame: frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + value;
    }
    feed.emit_total(io: io, total: total)?;
    return Ok(unit);
}

